const body = $input.item.json.body || $input.item.json;
if (!body.topic || !body.primaryKeyword) {
  throw new Error('Missing Topic Parameters: topic and primaryKeyword are required.');
}

return {
  json: {
    jobId: 'job_' + Math.random().toString(36).substring(2, 10),
    topic: body.topic,
    keyword: body.primaryKeyword,
    targetAudience: body.targetAudience || 'B2B Technical Leaders',
    wordCountTarget: body.wordCountTarget || 1400,
    slug: (body.primaryKeyword).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
    requestedAt: new Date().toISOString()
  }
};
